// Load verified mock upcoming fixtures for safe offline testing
const mockUpcoming = {
  "get": "fixtures",
  "parameters": {
    "league": "39",
    "season": "2026",
    "status": "NS",
    "from": "2026-11-20",
    "to": "2026-11-30"
  },
  "errors": [],
  "results": 3,
  "paging": {
    "current": 1,
    "total": 1
  },
  "response": [
    {
      "fixture": {
        "id": 3001,
        "date": "2026-11-21T17:30:00Z",
        "status": {
